// INERT fixture (#156): a DEPENDENCY that touches Web Storage. Vendored under a committed
// node_modules/ so capwall's attribution charges these calls to `storage-dep` rather than to the
// application. No real secrets, no network, no filesystem path of its own — the only file that
// moves is the one the OPERATOR chose with --localstorage-file.
//
// Every entry point reports `OK:<value>` or `BLOCKED:<pkg>` so the test can tell a denial from a
// failure, and so an un-guarded run and a guarded-but-allowed run are distinguishable.
function attempt(label, fn) {
  try {
    return `${label}:OK:${JSON.stringify(fn())}`;
  } catch (err) {
    if (err && err.name === "CapabilityError") return `${label}:BLOCKED:${err.pkg ?? "?"}`;
    return `${label}:ERROR:${err && err.name}`;
  }
}

exports.readItem = (key) => attempt("getItem", () => globalThis.localStorage.getItem(key));
exports.writeItem = (key, value) =>
  attempt("setItem", () => {
    globalThis.localStorage.setItem(key, value);
    return "written";
  });
exports.readLength = () => attempt("length", () => globalThis.localStorage.length);
exports.readKey = (i) => attempt("key", () => globalThis.localStorage.key(i));
exports.removeItem = (key) =>
  attempt("removeItem", () => {
    globalThis.localStorage.removeItem(key);
    return "removed";
  });
exports.clearAll = () =>
  attempt("clear", () => {
    globalThis.localStorage.clear();
    return "cleared";
  });

// sessionStorage is IN-MEMORY: no file, so nothing for an `fs` grant to be about. Asserted to be
// un-gated, which is the row that proves the guard is not just "deny everything storage-shaped".
exports.sessionRoundTrip = () =>
  attempt("session", () => {
    globalThis.sessionStorage.setItem("s", "v");
    return globalThis.sessionStorage.getItem("s");
  });

// Identity, so the test can assert capwall's view is still a Storage to ordinary code.
exports.shape = () => ({
  instanceOfStorage: globalThis.localStorage instanceof globalThis.Storage,
  protoIsStoragePrototype:
    Object.getPrototypeOf(globalThis.localStorage) === globalThis.Storage.prototype,
});
